// Offsets are generated by the binary builder. The historical P2 prefix is
// kept stable; appended P3 fields never rely on a guessed payload address.
export function nativePlayers(heap,mailbox,patch){
  const view=new DataView(heap.buffer),code=mailbox-patch.mailbox_cs_offset;
  const data=code+(patch.data_segment-patch.code_segment)*16,p=patch.mailbox_offsets;
  const count=heap[code+patch.entry_map.player_count];
  if(![2,3].includes(count))throw Error('原生玩家人数无效');
  const states=[data+0x36d0,mailbox+40,code+patch.entry_map.p3_state];
  const stocks=[data+0x4ad4,mailbox+82,code+patch.entry_map.p3_resources];
  const shots=[data+0xc4bc,mailbox+84,code+patch.entry_map.p3_shots];
  const overflows=[data+0x1e78,mailbox+88,code+patch.entry_map.p3_overflow];
  const xy=[mailbox+28,mailbox+32,code+patch.entry_map.p3_xy];
  // A JSPI yield may occur with a guest bound, or between guest callbacks.
  // Published stocks/positions stay canonical; raw entry timers do not.
  const active=heap[mailbox+90],guest=heap[code+patch.entry_map.guest_slot],liveStates=[];
  liveStates[active]=states[0];liveStates[active===0?guest:0]=states[1];liveStates[guest===1?2:1]=states[2];
  const characters=Array.from({length:count},(_,i)=>heap[code+patch.entry_map.run_config+2+i*3]);
  const positions=xy.slice(0,count).map(at=>[view.getInt16(at,true)/16,view.getInt16(at+2,true)/16]);
  const players=states.slice(0,count).map((at,i)=>{
    const n=mailbox+p.stats+i*4;
    const schema=patch.personal_stats,s=schema?code+schema.cs_offset:-1;
    const personal=s<0?{}:{score:view.getUint32(s,true),highScore:view.getUint32(s+4,true),stagePoint:view.getUint16(s+8,true),point:view.getUint16(s+10,true),dream:heap[s+12],dreamCount:heap[s+13],graze:view.getUint16(s+14,true),totalItems:view.getUint16(s+16,true),totalPoint:view.getUint16(s+18,true),maxPoint:view.getUint16(s+20,true),scoreExtends:heap[s+23]};
    return {lives:heap[n],bombs:heap[n+1],power:heap[n+2],miss:heap[n+3],entry:heap[liveStates[i]+31],ghost:!!heap[mailbox+p.out_flags+i],offline:heap[mailbox+p.out_flags+i]===2,rescue:heap[mailbox+p.rescue_progress+i],rescueTarget:heap[code+patch.entry_map.rescue_target+i],...personal};
  });
  return {count,code,data,states,liveStates,stocks,shots,overflows,xy,characters,positions,players};
}
